import { createBuilding, ImagePanel, ProductDisplay, TextPanel } from './Building.js';
export function createBuildingObject(definition, path = 'object') {
    if (definition.type === 'building') {
        const building = createBuilding(definition);
        if (definition.position)
            building.position.fromArray(definition.position);
        return building;
    }
    if (definition.type === 'text-panel') {
        if (typeof definition.text !== 'string')
            throw new Error(`${path}.text must be a string.`);
        return new TextPanel(definition.text, definition);
    }
    if (definition.type === 'image-panel') {
        if (typeof definition.source !== 'string')
            throw new Error(`${path}.source must be a string.`);
        return new ImagePanel(definition.source, definition);
    }
    if (definition.type === 'product-display') {
        if (typeof definition.productId !== 'string')
            throw new Error(`${path}.productId must be a string.`);
        return new ProductDisplay(definition.productId, definition);
    }
    throw new Error(`${path}.type is not a supported building object.`);
}